/**
 * Loads Twitch's official interactive embed (`Twitch.Player`) exactly once.
 * Docs: https://dev.twitch.tv/docs/embed/video-and-clips/
 */

export interface TwitchPlayerOptions {
  width: number | string;
  height: number | string;
  channel?: string;
  video?: string;
  /** Domains embedding the player. Twitch refuses to play without the current one. */
  parent: string[];
  autoplay?: boolean;
  muted?: boolean;
  /** VOD start time, "1h2m3s". */
  time?: string;
}

/** The documented subset of Twitch.Player we use. */
export interface TwitchPlayer {
  addEventListener(event: string, callback: () => void): void;
  play(): void;
  pause(): void;
  /** Seconds. VODs only. */
  seek(seconds: number): void;
  /** Seconds. VODs only; live streams don't report a playhead. */
  getCurrentTime(): number;
  getEnded(): boolean;
  isPaused(): boolean;
  getChannel(): string | undefined;
}

export interface TwitchPlayerStatic {
  new (target: string | HTMLElement, options: TwitchPlayerOptions): TwitchPlayer;
  READY: string;
  PLAY: string;
  PLAYING: string;
  PAUSE: string;
  ENDED: string;
  ONLINE: string;
  OFFLINE: string;
  PLAYBACK_BLOCKED: string;
  SEEK: string;
}

declare global {
  interface Window {
    Twitch?: { Player?: TwitchPlayerStatic };
  }
}

const SRC = "https://player.twitch.tv/js/embed/v1.js";
let loading: Promise<TwitchPlayerStatic> | null = null;

export function loadTwitchEmbedApi(): Promise<TwitchPlayerStatic> {
  if (typeof window === "undefined") return Promise.reject(new Error("The Twitch player needs a browser."));
  if (window.Twitch?.Player) return Promise.resolve(window.Twitch.Player);
  if (loading) return loading;

  loading = new Promise<TwitchPlayerStatic>((resolve, reject) => {
    const script = document.createElement("script");
    script.src = SRC;
    script.async = true;
    script.onload = () => {
      const Player = window.Twitch?.Player;
      if (Player) resolve(Player);
      else fail();
    };
    const fail = () => {
      loading = null;
      script.remove();
      reject(new Error("Couldn't load the Twitch player. Check your connection or disable blockers for twitch.tv."));
    };
    script.onerror = fail;
    document.head.appendChild(script);
  });
  return loading;
}

import type { ParsedVideo, ParseProblem } from "../types";
import { parseYouTubeTime } from "../youtube/parse";

const HOSTS = new Set(["twitch.tv", "www.twitch.tv", "m.twitch.tv", "go.twitch.tv", "player.twitch.tv"]);
const CLIP_HOSTS = new Set(["clips.twitch.tv"]);
/** Twitch logins: letters, digits and underscores. */
const LOGIN = /^[A-Za-z0-9_]{2,25}$/;
const VIDEO_ID = /^\d{5,}$/;
/** First path segments that are Twitch pages, not channels. */
const RESERVED = new Set([
  "bits", "broadcast", "creatorcamp", "dashboard", "directory", "downloads", "drops", "embed",
  "friends", "inventory", "jobs", "login", "messages", "moderator", "p", "payments", "popout",
  "prime", "privacy", "products", "search", "settings", "signup", "store", "subscriptions",
  "team", "turbo", "u", "user", "videos", "wallet",
]);

const CLIP_MESSAGE =
  "Twitch clips can't be captioned here yet, because Twitch's clip player has no playback controls for other sites. Open the clip on Twitch and use the Heard Chrome extension, or paste the channel or video link.";

/** Seconds → Twitch's "1h2m3s" time format. */
export function formatTwitchTime(seconds: number): string {
  const s = Math.max(0, Math.floor(seconds));
  return `${Math.floor(s / 3600)}h${Math.floor((s % 3600) / 60)}m${s % 60}s`;
}

function vod(id: string, url: URL): ParsedVideo {
  const startSeconds = parseYouTubeTime(url.searchParams.get("t") ?? url.searchParams.get("time"));
  const canonical = new URL(`https://www.twitch.tv/videos/${id}`);
  if (startSeconds) canonical.searchParams.set("t", formatTwitchTime(startSeconds));
  return {
    providerId: "twitch",
    key: `twitch:video:${id}`,
    canonicalUrl: canonical.toString(),
    embed: { videoId: id },
    startSeconds,
    maybeLive: false,
  };
}

function channel(login: string): ParsedVideo {
  const name = login.toLowerCase();
  return {
    providerId: "twitch",
    key: `twitch:channel:${name}`,
    canonicalUrl: `https://www.twitch.tv/${name}`,
    embed: { channel: name },
    maybeLive: true,
  };
}

function clip(url: URL): ParseProblem {
  const open = new URL(url.toString());
  open.protocol = "https:";
  return { providerId: "twitch", kind: "clip", platformName: "Twitch", openUrl: open.toString(), message: CLIP_MESSAGE };
}

export function parseTwitchUrl(url: URL): ParsedVideo | ParseProblem | null {
  const host = url.hostname.toLowerCase();
  const segs = url.pathname.split("/").filter(Boolean);

  if (CLIP_HOSTS.has(host)) return segs[0] || url.searchParams.get("clip") ? clip(url) : null;
  if (!HOSTS.has(host)) return null;

  // The embed player's own URL: player.twitch.tv/?channel=… or ?video=v123.
  if (host === "player.twitch.tv") {
    const v = url.searchParams.get("video")?.replace(/^v/, "");
    if (v && VIDEO_ID.test(v)) return vod(v, url);
    const c = url.searchParams.get("channel");
    return c && LOGIN.test(c) ? channel(c) : null;
  }

  const [first, second, third] = segs;
  if (!first) return null;

  if (first === "videos" && second && VIDEO_ID.test(second)) return vod(second, url);
  if (RESERVED.has(first.toLowerCase()) || !LOGIN.test(first)) return null;
  // twitch.tv/<channel>/clip/<slug>
  if (second === "clip" && third) return clip(url);
  // Older VOD links: twitch.tv/<channel>/v/<id> or /video/<id>.
  if ((second === "v" || second === "video") && third && VIDEO_ID.test(third)) return vod(third, url);
  // The channel page, or its about / schedule tabs: caption whatever is live there.
  if (!second || second === "about" || second === "schedule") return channel(first);
  return null;
}

import type { PlayerAdapter, PlayerEvents, PlayerState, ParsedVideo, VideoProvider } from "../types";
import { loadTwitchEmbedApi, type TwitchPlayer } from "./embed-api";
import { formatTwitchTime, parseTwitchUrl } from "./parse";

export { parseTwitchUrl, formatTwitchTime } from "./parse";

let nextId = 0;

function createAdapter(player: TwitchPlayer, wrapper: HTMLElement, video: ParsedVideo, live: { online: boolean }, state: { current: PlayerState; ready: boolean; queuedPlay: boolean }): PlayerAdapter {
  const isVod = typeof video.embed.videoId === "string";
  return {
    // Twitch reports a playhead only for VODs; for live channels the watch page falls back
    // to stream time (hasTimeline() is false), so this value isn't used for transcript times.
    getCurrentTime: () => {
      if (!isVod || !state.ready) return 0;
      try {
        return player.getCurrentTime() || 0;
      } catch {
        return 0;
      }
    },
    hasTimeline: () => isVod,
    seekTo: (s) => {
      if (!isVod || !state.ready) return;
      player.seek(Math.max(0, s));
      if (state.current !== "playing") player.play();
    },
    play: () => {
      if (state.ready) player.play();
      else state.queuedPlay = true;
    },
    getState: () => state.current,
    isLive: () => !isVod && (live.online || state.current === "playing" || video.maybeLive),
    getTitle: () => {
      if (!state.ready) return null;
      try {
        const name = player.getChannel()?.trim();
        if (!name) return null;
        return isVod ? `${name} · Twitch video` : name;
      } catch {
        return null;
      }
    },
    getPlaybackRate: () => 1,
    destroy: () => {
      // Twitch.Player has no destroy(); removing the wrapper removes its iframe.
      wrapper.remove();
    },
  };
}

export const twitchProvider: VideoProvider = {
  id: "twitch",
  name: "Twitch",
  capabilities: {
    siteHost: "twitch.tv",
    // Twitch embed rule 1.3: embeds "should not be obscured in any way by other page
    // elements" (see docs/provider-policies.md), so captions render below the player.
    allowsCaptionOverlay: false,
    minPlayerSize: { width: 400, height: 300 },
  },
  parse: parseTwitchUrl,

  async mount(host, video, events: PlayerEvents) {
    const Player = await loadTwitchEmbedApi();
    const wrapper = document.createElement("div");
    wrapper.className = "h-full w-full";
    const target = document.createElement("div");
    target.id = `heard-twitch-${++nextId}`;
    target.className = "h-full w-full";
    wrapper.appendChild(target);
    host.appendChild(wrapper);

    const options = {
      width: "100%",
      height: "100%",
      // Twitch only plays inside the domains listed here.
      parent: [window.location.hostname],
      autoplay: false,
      ...(typeof video.embed.videoId === "string"
        ? { video: `v${video.embed.videoId}`, time: video.startSeconds ? formatTwitchTime(video.startSeconds) : undefined }
        : { channel: String(video.embed.channel) }),
    };
    const player = new Player(target, options);
    const iframe = wrapper.querySelector("iframe");
    if (iframe) iframe.title = "Twitch video player";

    const live = { online: false };
    const state = { current: "unstarted" as PlayerState, ready: false, queuedPlay: false };
    let everPlayed = false;
    const set = (next: PlayerState) => {
      if (state.current === next) return;
      state.current = next;
      events.onStateChange?.(next);
    };

    player.addEventListener(Player.READY, () => {
      state.ready = true;
      if (state.queuedPlay) player.play();
      events.onReady?.();
    });
    player.addEventListener(Player.PLAY, () => set("buffering"));
    player.addEventListener(Player.PLAYING, () => {
      everPlayed = true;
      set("playing");
    });
    player.addEventListener(Player.PAUSE, () => set("paused"));
    player.addEventListener(Player.ENDED, () => set("ended"));
    player.addEventListener(Player.ONLINE, () => {
      live.online = true;
    });
    player.addEventListener(Player.OFFLINE, () => {
      live.online = false;
      if (typeof video.embed.channel !== "string") return;
      if (everPlayed) set("ended");
      else
        events.onError?.({
          code: "offline",
          embeddingBlocked: false,
          message: `${video.embed.channel} isn't live on Twitch right now. Come back when the stream starts, or open the channel on Twitch to watch past broadcasts.`,
        });
    });
    player.addEventListener(Player.PLAYBACK_BLOCKED, () => set("paused"));

    return createAdapter(player, wrapper, video, live, state);
  },
};

