function viewport() {
  return { w: window.innerWidth, h: window.innerHeight };
}

function defaultLayout(): OverlayLayout {
  const { w, h } = viewport();
  const width = Math.round(Math.min(760, w * 0.8));
  return { x: (w - width) / 2 / w, y: Math.max(0, h - 190) / h, width };
}

/** Layout fractions → on-screen pixels, clamped so the box is always fully visible. */
function place(layout: OverlayLayout, boxHeight: number) {
  const { w, h } = viewport();
  const width = Math.max(Math.min(MIN_WIDTH, w - 2 * EDGE), Math.min(layout.width, w - 2 * EDGE));
  const left = Math.min(Math.max(EDGE, layout.x * w), Math.max(EDGE, w - width - EDGE));
  const top = Math.min(Math.max(EDGE, layout.y * h), Math.max(EDGE, h - boxHeight - EDGE));
  return { left, top, width };
}

function normalizeLayout(v: unknown): OverlayLayout | null {
  if (typeof v !== "object" || v === null) return null;
  const { x, y, width } = v as Record<string, unknown>;
  if (![x, y, width].every((n) => typeof n === "number" && Number.isFinite(n))) return null;
  // Layouts saved before the box followed the video weren't chosen against it: ignore them.
  if ((v as { manual?: unknown }).manual !== true) return null;
  return { x: x as number, y: y as number, width: width as number, manual: true };
}

/* ------------------------------ the page's video ------------------------------ */

interface MainVideo {
  rect: Rect;
  /** Playing but muted (or at zero volume): the tab is silent, so there's nothing to caption. */
  silent: boolean;
}

/** The video people are most likely watching (see pickMainVideo). */
function findMainVideo(): MainVideo | null {
  const videos = Array.from(document.querySelectorAll("video"));
  const candidates = videos.map((v) => {
    const r = v.getBoundingClientRect();
    return {
      rect: { left: r.left, top: r.top, width: r.width, height: r.height },
      paused: v.paused,
      audible: !v.muted && v.volume > 0,
    };
  });
  const i = pickMainVideo(candidates, viewport());
  if (i < 0) return null;
  const c = candidates[i]!;
  return { rect: c.rect, silent: !c.paused && !c.audible };
}

/** Tracks the main video's on-screen box (it moves with scrolling, theater mode, fullscreen). */
function useMainVideo(): MainVideo | null {
  const [video, setVideo] = useState<MainVideo | null>(null);
  useEffect(() => {
    let raf = 0;
    const measure = () => {
      raf = 0;
      const next = findMainVideo();
      setVideo((prev) => {
        if (!prev || !next) return next === prev ? prev : next;
        const a = prev.rect;
        const b = next.rect;
        const same =
          prev.silent === next.silent &&
          Math.abs(a.left - b.left) < 1 &&
          Math.abs(a.top - b.top) < 1 &&
          Math.abs(a.width - b.width) < 1 &&
          Math.abs(a.height - b.height) < 1;
        return same ? prev : next;
      });
    };
    const schedule = () => {
      if (!raf) raf = requestAnimationFrame(measure);
    };
    measure();
    const timer = window.setInterval(schedule, 400);
    window.addEventListener("scroll", schedule, { capture: true, passive: true });
    window.addEventListener("resize", schedule);
    document.addEventListener("fullscreenchange", schedule);
    // Mute / unmute and play / pause don't bubble, but they're visible in the capture phase.
    document.addEventListener("volumechange", schedule, true);
    document.addEventListener("play", schedule, true);
    document.addEventListener("pause", schedule, true);
    return () => {
      if (raf) cancelAnimationFrame(raf);
      window.clearInterval(timer);
      window.removeEventListener("scroll", schedule, { capture: true });
      window.removeEventListener("resize", schedule);
      document.removeEventListener("fullscreenchange", schedule);
      document.removeEventListener("volumechange", schedule, true);
      document.removeEventListener("play", schedule, true);
      document.removeEventListener("pause", schedule, true);
    };
  }, []);
  return video;
}

